     1	package cli
     2	
     3	import (
     4		"context"
     5		"fmt"
     6		"io"
     7		"strings"
     8	
     9		"charm.land/huh/v2"
    10		"github.com/spf13/cobra"
    11	
    12		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
    13		"github.com/entireio/cli/cmd/entire/cli/gitremote"
    14		"github.com/entireio/cli/cmd/entire/cli/interactive"
    15		"github.com/entireio/cli/cmd/entire/cli/paths"
    16		"github.com/entireio/cli/cmd/entire/cli/settings"
    17		"github.com/entireio/cli/cmd/entire/cli/strategy"
    18	)
    19	
    20	const flagCheckpointPushRemote = "checkpoint-push-remote"
    21	
    22	type enableCheckpointRemoteKey struct{}
    23	
    24	// A choice is prepared before setup touches the repository, then saved after
    25	// ordinary setup settings so those writes cannot overwrite the local choice.
    26	type enableCheckpointRemoteChoice struct {
    27		name               string
    28		changed            bool
    29		saved              bool
    30		dedicatedRequested bool
    31		pending            bool // Fresh setup asks after agent selection, before installing hooks.
    32	}
    33	
    34	func prepareEnableCheckpointRemoteCommand(cmd *cobra.Command, opts *EnableOptions) error {
    35		if cmd.Flags().Changed(flagCheckpointPushRemote) && cmd.Flags().Changed(flagCheckpointRemote) {
    36			return fmt.Errorf("--%s and --%s cannot be combined", flagCheckpointPushRemote, flagCheckpointRemote)
    37		}
    38		explicit := cmd.Flags().Changed(flagCheckpointPushRemote)
    39		canPrompt := !cmd.Flags().Changed(agentFlagName) && interactive.CanPromptInteractively()
    40		pending := canPrompt && !explicit && !settings.IsSetUpAny(cmd.Context())
    41		choice, err := prepareEnableCheckpointRemoteSelection(cmd.Context(), *opts, explicit, canPrompt && !pending, nil)
    42		if err != nil {
    43			cmd.SilenceUsage = true
    44			return err
    45		}
    46		choice.pending = pending
    47		opts.checkpointRemoteChoice = choice
    48		cmd.SetContext(context.WithValue(cmd.Context(), enableCheckpointRemoteKey{}, choice))
    49		return nil
    50	}
    51	
    52	func (c *enableCheckpointRemoteChoice) selectAfterAgents(ctx context.Context, opts EnableOptions, selectFn func(context.Context, []huh.Option[string]) (string, error)) error {
    53		if c == nil || !c.pending {
    54			return nil
    55		}
    56		choice, err := prepareEnableCheckpointRemoteSelection(ctx, opts, false, true, selectFn)
    57		if err != nil {
    58			return err
    59		}
    60		// Keep the pointer shared with the command's deferred destination report.
    61		*c = *choice
    62		return nil
    63	}
    64	
    65	func prepareEnableCheckpointRemoteSelection(ctx context.Context, opts EnableOptions, explicit, canPrompt bool, selectFn func(context.Context, []huh.Option[string]) (string, error)) (*enableCheckpointRemoteChoice, error) {
    66		choice, err := prepareEnableCheckpointRemote(ctx, opts, explicit)
    67		if err != nil || explicit || !canPrompt || opts.Yes || opts.SkipPushSessions || opts.CheckpointRemote != "" {
    68			return choice, err
    69		}
    70		root, err := paths.WorktreeRoot(ctx)
    71		if err != nil {
    72			return choice, nil //nolint:nilerr // Repository bootstrap has not run yet; there is no existing destination to select.
    73		}
    74		s, err := settings.Load(ctx)
    75		if err != nil {
    76			return nil, fmt.Errorf("load checkpoint destination settings: %w", err)
    77		}
    78		if s.IsPushSessionsDisabled() {
    79			return choice, nil
    80		}
    81		resolved, resolveErr := strategy.ResolveCheckpointSyncRemote(ctx)
    82		if resolveErr == nil && resolved.Name != "" {
    83			_, dedicated, err := remote.PushURL(ctx, resolved.Name)
    84			if err != nil {
    85				return nil, fmt.Errorf("resolve dedicated checkpoint destination: %w", err)
    86			}
    87			if dedicated {
    88				return choice, nil
    89			}
    90		}
    91		var eligibilityErr error
    92		if resolveErr == nil && resolved.Name != "" {
    93			eligibilityErr = validateCheckpointPushRemote(ctx, root, resolved.Name)
    94			if eligibilityErr == nil && s.GetCheckpointPushRemote() != "" {
    95				return choice, nil
    96			}
    97		}
    98		topology := inspectRemoteTopology(ctx)
    99		if resolveErr != nil {
   100			for _, d := range topology.destinations {
   101				if d.pinned {
   102					return choice, nil
   103				}
   104			}
   105		}
   106		if len(topology.destinations) == 0 || (len(topology.destinations) == 1 && resolveErr == nil && eligibilityErr == nil) {
   107			return choice, nil
   108		}
   109		current := resolved.Name
   110		label := fmt.Sprintf("Keep current destination: %s (%s; no settings change)", current, checkpointRemoteSourceLabel(resolved.Source))
   111		if resolveErr != nil {
   112			current = s.GetCheckpointPushRemote()
   113			label = fmt.Sprintf("Keep invalid destination: %s (checkpoint sync remains disabled; no settings change)", current)
   114		} else if eligibilityErr != nil {
   115			label = fmt.Sprintf("Keep unsupported destination: %s (no configured fetch URL; no settings change)", current)
   116		}
   117		options := []huh.Option[string]{huh.NewOption(label, "")}
   118		for _, d := range topology.destinations {
   119			if d.pinned {
   120				continue
   121			}
   122			if err := validateCheckpointPushRemote(ctx, root, d.name); err != nil {
   123				continue
   124			}
   125			urls := make([]string, 0, len(d.pushURLs))
   126			for _, u := range d.pushURLs {
   127				urls = append(urls, gitremote.RedactURLOrPath(u))
   128			}
   129			if d.name == current {
   130				options[0].Key += " — " + strings.Join(urls, ", ")
   131				continue
   132			}
   133			options = append(options, huh.NewOption(fmt.Sprintf("%s — %s", d.name, strings.Join(urls, ", ")), d.name))
   134		}
   135		if len(options) == 1 {
   136			return choice, nil
   137		}
   138		if selectFn == nil {
   139			selectFn = func(ctx context.Context, options []huh.Option[string]) (string, error) {
   140				return selectEnableCheckpointRemote(ctx, options, len(topology.destinations))
   141			}
   142		}
   143		name, err := selectFn(ctx, options)
   144		if err != nil {
   145			return nil, fmt.Errorf("checkpoint destination selection cancelled: %w", err)
   146		}
   147		if err := ctx.Err(); err != nil {
   148			return nil, fmt.Errorf("checkpoint destination selection cancelled: %w", err)
   149		}
   150		if name == "" {
   151			return choice, nil
   152		}
   153		// Apply exactly the same strict validation as the explicit flag, including
   154		// dedicated-URL precedence. Preparing a selection never writes settings.
   155		opts.CheckpointPushRemote = name
   156		return prepareEnableCheckpointRemote(ctx, opts, true)
   157	}
   158	
   159	func selectEnableCheckpointRemote(ctx context.Context, options []huh.Option[string], remoteCount int) (string, error) {
   160		var selected string
   161		keys := huh.NewDefaultKeyMap()
   162		keys.Quit.SetKeys("ctrl+c", "esc")
   163		form := NewAccessibleForm(huh.NewGroup(huh.NewSelect[string]().
   164			Title("Where should checkpoints go?").
   165			Description(fmt.Sprintf("Detected %d Git remotes. Choose where this clone uploads checkpoints. Keeping the current destination changes no destination settings.", remoteCount)).
   166			Options(options...).Value(&selected))).WithKeyMap(keys)
   167		if err := form.RunWithContext(ctx); err != nil {
   168			return "", fmt.Errorf("checkpoint destination form: %w", err)
   169		}
   170		return selected, nil
   171	}
   172	
   173	func checkpointRemoteSourceLabel(source strategy.CheckpointSyncRemoteSource) string {
   174		if source == strategy.SyncRemoteSourceConfig {
   175			return "configured"
   176		}
   177		if source == strategy.SyncRemoteSourceObserved {
   178			return "previously selected"
   179		}
   180		return "automatic"
   181	}
   182	
   183	func prepareEnableCheckpointRemote(ctx context.Context, opts EnableOptions, explicit bool) (*enableCheckpointRemoteChoice, error) {
